	describe("URL State Management", () => {
		it("initializes dates from URL parameters when provided", async () => {
			const initialRoute =
				"/teams/1/metrics?startDate=2025-01-01&endDate=2025-01-31";

			render(
				<MemoryRouter initialEntries={[initialRoute]}>
