	describe("Date range URL round-trip (Bug #5566)", () => {
		/**
		 * The dashboards used to write the startDate/endDate params in UTC while the
		 * request layer built them from local Y/M/D parts, so a reloaded or shared
		 * link described a window shifted by one calendar day. These tests only bite
		 * at a non-zero UTC offset — the suite pins one (see the `test` script).
		 */
		const UrlProbe = () => {
			const [params] = useSearchParams();
			return (
				<>
					<span data-testid="url-start-date">{params.get("startDate")}</span>
					<span data-testid="url-end-date">{params.get("endDate")}</span>
				</>
			);
		};

		const renderDashboard = (initialRoute: string) =>
			render(
				<MemoryRouter initialEntries={[initialRoute]}>
					<BaseMetricsView
						entity={mockTeam}
						metricsService={mockMetricsService}
						title="Work Items"
						defaultDateRange={30}
						doingStates={["To Do", "In Progress", "Review"]}
					/>
					<UrlProbe />
				</MemoryRouter>,
			);

		const localDayOf = (date: Date) =>
			`${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(
				date.getDate(),
			).padStart(2, "0")}`;

		const lastRequestedStartDay = () => {
			const calls = (mockMetricsService.getThroughput as Mock).mock.calls;
			return localDayOf(calls[calls.length - 1][1] as Date);
		};

		it("writes the picked calendar day to the URL, not the UTC one", async () => {
			renderDashboard("/teams/1/metrics");
			await screen.findByTestId("pick-fixed-start-date");

			fireEvent.click(screen.getByTestId("pick-fixed-start-date"));

			await waitFor(() => {
				expect(lastRequestedStartDay()).toBe("2026-06-15");
			});
			expect(screen.getByTestId("url-start-date").textContent).toBe(
				"2026-06-15",
			);
		});

		it("requests the very calendar day the URL names", async () => {
			renderDashboard(
				"/teams/1/metrics?startDate=2026-06-15&endDate=2026-07-15",
			);

			await waitFor(() => {
				expect(mockMetricsService.getThroughput).toHaveBeenCalled();
			});

			expect(lastRequestedStartDay()).toBe("2026-06-15");
			const calls = (mockMetricsService.getThroughput as Mock).mock.calls;
			expect(localDayOf(calls[calls.length - 1][2] as Date)).toBe("2026-07-15");
		});

		it("survives a full round-trip through the URL", async () => {
			const { unmount } = renderDashboard("/teams/1/metrics");
			await screen.findByTestId("pick-fixed-start-date");
			fireEvent.click(screen.getByTestId("pick-fixed-start-date"));
			await waitFor(() => {
				expect(screen.getByTestId("url-start-date").textContent).toBeTruthy();
			});
			const sharedLink = `/teams/1/metrics?startDate=${screen.getByTestId("url-start-date").textContent}&endDate=${screen.getByTestId("url-end-date").textContent}`;
			unmount();

			renderDashboard(sharedLink);

			await waitFor(() => {
				expect(lastRequestedStartDay()).toBe("2026-06-15");
			});
		});
	});
	describe("Unusable dates never reach the dashboard state", () => {
		/**
		 * A string the browser cannot make sense of still yields a Date object, and
		 * an object is truthy, so a plain null check waves it straight through into
		 * state and into the URL, where it reappears as NaN and takes the page down.
		 * The picker in front of these handlers already refuses such a date; the
		 * guard here is so the next caller wired to them - another picker, a deep
		 * link, a component that does not exist yet - cannot bring the crash back.
		 */
		const UrlProbe = () => {
			const [params] = useSearchParams();
			return (
				<>
					<span data-testid="url-start-date">{params.get("startDate")}</span>
					<span data-testid="url-end-date">{params.get("endDate")}</span>
				</>
			);
		};

		const renderDashboard = (startDate = "2026-06-15") =>
			render(
				<MemoryRouter
					initialEntries={[
						`/teams/1/metrics?startDate=${startDate}&endDate=2026-07-15`,
					]}
				>
					<BaseMetricsView
						entity={mockTeam}
						metricsService={mockMetricsService}
						title="Work Items"
						defaultDateRange={30}
						doingStates={["To Do", "In Progress", "Review"]}
					/>
					<UrlProbe />
				</MemoryRouter>,
			);

		const shownWindow = () => ({
			start: screen.getByTestId("start-date").textContent,
			end: screen.getByTestId("end-date").textContent,
			urlStart: screen.getByTestId("url-start-date").textContent,
			urlEnd: screen.getByTestId("url-end-date").textContent,
		});

		it.each([
			"pick-unusable-start-date",
			"pick-unusable-end-date",
			"pick-no-start-date",
			"pick-no-end-date",
		])(
			"leaves the window untouched when the picker fires %s",
			async (testId) => {
				renderDashboard();
				await screen.findByTestId(testId);
				const before = shownWindow();

				fireEvent.click(screen.getByTestId(testId));

				expect(shownWindow()).toEqual(before);
				expect(before.urlStart).toBe("2026-06-15");
				expect(before.urlEnd).toBe("2026-07-15");
			},
		);

		it("still moves the window when the picker hands over a real date", async () => {
			// Opened on a different day from the one the picker hands over, so the
			// assertion cannot be satisfied by a click that did nothing at all.
			renderDashboard("2026-05-01");
			await screen.findByTestId("pick-fixed-start-date");
			expect(screen.getByTestId("url-start-date").textContent).toBe(
				"2026-05-01",
			);

			fireEvent.click(screen.getByTestId("pick-fixed-start-date"));

			await waitFor(() => {
				expect(screen.getByTestId("url-start-date").textContent).toBe(
					"2026-06-15",
				);
			});
			expect(screen.getByTestId("start-date").textContent).not.toBe("unusable");
		});
	});

	/**
	 * Bug #5571 — "we load a LOT of data on first open … then, when I switch the metrics
	 * category, it barely loads anything". Every widget's data was fetched on mount no matter
	 * which category was actually on screen, so the default Flow Overview paid for Predictability,
	 * Flow Metrics and Portfolio as well. The fix gates each fetch on the categories the user has
	 * actually visited.
	 *
	 * The spies sit on the IMetricsService / IBlackoutPeriodService ports — the hexagonal
	 * boundary — not on the HTTP client, so these tests describe the contract between the view
	 * and its driven ports rather than a transport detail.
	 */
	describe("category-scoped fetching (Bug #5571)", () => {
		type TeamMock = ReturnType<typeof createMockMetricsService<IWorkItem>>;
		type PortfolioMock = ReturnType<typeof createMockMetricsService<IFeature>>;
		type BlackoutMock = ReturnType<typeof createMockBlackoutPeriodService>;

		const createBlackoutService = (): BlackoutMock => {
			const service = createMockBlackoutPeriodService();
			service.getAll = vi.fn().mockResolvedValue([]);
			return service;
		};

		const createTeamService = () => ({
			...createMockMetricsService<IWorkItem>(),
			getFeaturesInProgress: vi.fn().mockResolvedValue([]),
		});

		const createPortfolioService = () => createMockMetricsService<IFeature>();

		const presetCategory = (
			ownerType: "team" | "portfolio",
			ownerId: number,
			category: CategoryKey,
		) =>
			localStorage.setItem(
				`lighthouse:metrics:${ownerType}:${ownerId}:category`,
				category,
			);

		const renderView = (
			ownerType: "team" | "portfolio",
			svc: TeamMock | PortfolioMock,
			blackout: BlackoutMock,
		) =>
			render(
				<MemoryRouter>
					<ApiServiceContext.Provider
						value={createMockApiServiceContext({
							blackoutPeriodService: blackout,
						})}
					>
						<BaseMetricsView
							entity={ownerType === "team" ? mockTeam : mockProject}
							metricsService={svc as IMetricsService<IWorkItem>}
							title="Work Items"
							defaultDateRange={30}
							doingStates={["To Do", "In Progress", "Review"]}
						/>
					</ApiServiceContext.Provider>
				</MemoryRouter>,
			);

		/** Waits for the dashboard to mount and lets every resolved fetch flush into state, so a
		 *  "was never called" assertion cannot pass merely because it ran too early. */
		const settle = async () => {
			await waitFor(() => {
				expect(screen.getByTestId("dashboard-component")).toBeInTheDocument();
			});
			await act(async () => {
				await new Promise((resolve) => setTimeout(resolve, 0));
			});
		};

		const switchTo = async (category: CategoryKey) => {
			fireEvent.click(screen.getByTestId(`select-category-${category}`));
			await settle();
		};

		const testIdSuffixes = (prefix: string) =>
			screen
				.queryAllByTestId(new RegExp(`^${prefix}`))
				.map((element) => element.getAttribute("data-testid") ?? "")
				.map((id) => id.slice(prefix.length))
				.sort();

		const renderedWidgetHeaders = () => testIdSuffixes("widget-header-");

		const renderedWidgetViewData = () =>
			testIdSuffixes("widget-view-data-").filter(
				(suffix) =>
					!/^(title|count|highlight-title|highlight-values|sle)-/.test(suffix),
			);

		/** The factory hands the mock back behind its interface type, which hides the
		 *  owner-specific extras (`getFeaturesWorkedOnInfo`, the feature-size family). Reading the
		 *  spies by name keeps the expectation maps below declarative. */
		const spiesOf = (svc: TeamMock | PortfolioMock): Record<string, Mock> =>
			svc as unknown as Record<string, Mock>;

		/** What Flow Overview legitimately needs, and how often. `getWorkItemAgePercentiles` is
		 *  twice by design: the current window plus the previous one that feeds the trend arrow. */

		const flowOverviewFetches = (
			svc: Record<string, Mock>,
			ownerType: "team" | "portfolio",
		): Record<string, { readonly spy: Mock; readonly times: number }> => ({
			"in-progress items": { spy: svc.getInProgressItems, times: 1 },
			"WIP overview info": { spy: svc.getWipOverviewInfo, times: 1 },
			"blocked items": { spy: svc.getBlockedItemsAtDate, times: 1 },
			"blocked count history": { spy: svc.getBlockedCountHistory, times: 1 },
			"total work item age": { spy: svc.getTotalWorkItemAge, times: 1 },
			"total work item age info": {
				spy: svc.getTotalWorkItemAgeInfo,
				times: 1,
			},
			"predictability score": {
				spy: svc.getMultiItemForecastPredictabilityScore,
				times: 1,
			},
			"predictability score info": {
				spy: svc.getPredictabilityScoreInfo,
				times: 1,
			},
			"cycle time data": { spy: svc.getCycleTimeData, times: 1 },
			"cycle time percentiles": { spy: svc.getCycleTimePercentiles, times: 1 },
			"cycle time percentiles info": {
				spy: svc.getCycleTimePercentilesInfo,
				times: 1,
			},
			"work item age percentiles": {
				spy: svc.getWorkItemAgePercentiles,
				times: 2,
			},
			throughput: { spy: svc.getThroughput, times: 1 },
			"throughput info": { spy: svc.getThroughputInfo, times: 1 },
			arrivals: { spy: svc.getArrivals, times: 1 },
			"arrivals info": { spy: svc.getArrivalsInfo, times: 1 },
			...(ownerType === "team"
				? {
						"flow efficiency": {
							spy: svc.getFlowEfficiencyInfoForTeam,
							times: 1,
						},
						"features worked on info": {
							spy: svc.getFeaturesWorkedOnInfo,
							times: 1,
						},
					}
				: {
						"flow efficiency": {
							spy: svc.getFlowEfficiencyInfoForPortfolio,
							times: 1,
						},
						"feature size percentiles info": {
							spy: svc.getFeatureSizePercentilesInfo,
							times: 1,
