				}
			},
		);

		it.each(ownerTypes)(
			"fetches each Flow Overview dependency exactly once on mount (%s)",
			async (ownerType) => {
				const { svc } = await mountFlowOverview(ownerType);

				for (const [name, { spy, times }] of Object.entries(
					flowOverviewFetches(spiesOf(svc), ownerType),
